101:     if (distanceXZ(hole.cup.position, nextX, nextZ) <= hole.cup.radius && speed <= CUP_CAPTURE_SPEED) {
102:       holed = true;
103:       travel += Math.hypot(nextX - x, nextZ - z);
104:       x = hole.cup.position.x;
105:       z = hole.cup.position.z;
